require 'config/auth.php'; require 'config/db.php'; require_permission('budget.edit'); require_once 'config/ledger.php';
$id=(int)($_GET['id']??$_POST['id']??0);if($id<=0)die('ไม่พบรหัสเอกสาร');
$s=$conn->prepare('SELECT * FROM budget_transfers WHERE id=?');$s->bind_param('i',$id);$s->execute();$doc=$s->get_result()->fetch_assoc();if(!$doc||!can_access_unit((int)$doc['unit_id'])){http_response_code(403);die('ไม่มีสิทธิ์แก้ไขเอกสารนี้');}
if($doc['cancelled_at']){http_response_code(409);exit('เอกสารนี้ถูกลบแล้ว ไม่สามารถแก้ไขได้');}
$error='';$units=$conn->query('SELECT id,unit_code,unit_name FROM units ORDER BY unit_code')->fetch_all(MYSQLI_ASSOC);
if($_SERVER['REQUEST_METHOD']==='POST'){
 $docNo=trim($_POST['doc_no']??'');$docDate=$_POST['doc_date']??'';$receive=$_POST['receive_date']?:null;$paying=(int)($_POST['paying_unit_id']??0);$subject=trim($_POST['subject']??'');$item=trim($_POST['item_name']??'');$gfmis=trim($_POST['gfmis_code']??'');$gfmisDate=$_POST['gfmis_date']?:null;$activity=trim($_POST['activity_code']??'');$amount=(float)($_POST['amount']??0);$control=trim($_POST['control_account_no']??'');$budget=trim($_POST['budget_code']??'');$fund=trim($_POST['source_fund']??'');$expense=trim($_POST['expense_category']??'');$itemType=trim($_POST['item_type']??'');$budgetTypes=implode(',',$_POST['budget_types']??[]);
 if($docNo===''||$docDate===''||$subject===''||$item===''||$amount<=0){$error='กรุณากรอกข้อมูลที่จำเป็นให้ครบ';}else{try{begin_financial_transaction($conn);
$lock=$conn->prepare('SELECT * FROM budget_transfers WHERE id=? AND cancelled_at IS NULL FOR UPDATE');$lock->bind_param('i',$id);$lock->execute();$live=$lock->get_result()->fetch_assoc();if(!$live||!can_access_unit((int)$live['unit_id']))throw new RuntimeException('เอกสารนี้ถูกลบแล้วหรือไม่มีสิทธิ์',403);ledger_assert_date_open($conn,(int)$live['unit_id'],(int)$live['fiscal_year'],$live['doc_date']);validate_fiscal_date($docDate,(int)$live['fiscal_year']);
$linked=$conn->prepare('SELECT id FROM control_accounts WHERE source_transfer_id=? FOR UPDATE');$linked->bind_param('i',$id);$linked->execute();$linkedAccount=$linked->get_result()->fetch_assoc();
if($linkedAccount){$class=classification_get($conn,(int)$linkedAccount['id']);if($class&&$expense!==$class['expense_code'])throw new DomainException('ไม่สามารถเปลี่ยนหมวดเงินของบัญชีคุมงบประมาณ ที่จำแนกแล้ว');}
$q=$conn->prepare('UPDATE budget_transfers SET doc_no=?,doc_date=?,paying_unit_id=NULLIF(?,0),receive_date=?,control_account_no=?,budget_code=?,source_fund=?,expense_category=?,item_type=?,subject=?,item_name=?,gfmis_code=?,gfmis_date=?,activity_code=?,budget_types=?,total_amount=?,updated_at=NOW() WHERE id=?');$q->bind_param('ssisssssssssssssi',$docNo,$docDate,$paying,$receive,$control,$budget,$fund,$expense,$itemType,$subject,$item,$gfmis,$gfmisDate,$activity,$budgetTypes,$amount,$id);$q->execute();$q=$conn->prepare('UPDATE budget_transfer_items SET description=?,amount=? WHERE transfer_id=?');$q->bind_param('ssi',$item,$amount,$id);$q->execute();db_replace_transaction($conn,(int)$doc['unit_id'],(int)$doc['fiscal_year'],$docDate,'transfer_in',$amount,'budget_transfers',$id,'เอกสารโอนงบเลขที่ '.$docNo,current_user_id());db_sync_control_account($conn,$id);if($linkedAccount){$checkAccount=ledger_account($conn,(int)$linkedAccount['id']);if(ledger_available_cents($checkAccount['received_amount'],ledger_totals($conn,(int)$linkedAccount['id']))<0)throw new DomainException('ลดวงเงินไม่ได้เพราะมีรายการตัดจ่ายหรือสงวนวงเงินแล้ว');}
$conn->commit();header('Location: budget_detail.php?id='.$id);exit;}catch(Throwable $e){$conn->rollback();$error='แก้ไขเอกสารไม่สำเร็จ: '.operation_error($e);}}
}
$types=['Annual'=>'งบประจำปี','Investment'=>'งบลงทุน','Central'=>'งบกลาง','Compensation'=>'งบบุคลากร','Carryover'=>'กันไว้เบิกเหลื่อมปี','Operating'=>'งบดำเนินงาน','Additional'=>'เพิ่มเติม/อื่น ๆ'];$selected=array_filter(explode(',',$doc['budget_types']??''));
