item_name')?></textarea><label>รหัส GFMIS</label><input name="gfmis_code" value="<?=ev($doc,'gfmis_code')?>"><label>วันที่ GFMIS</label><input type="date" name="gfmis_date" value="<?=ev($doc,'gfmis_date')?>"><label>รหัสกิจกรรมหลัก</label><input name="activity_code" value="<?=ev($doc,'activity_code')?>"><label>วงเงิน</label><input type="number" step="0.01" min="0.01" name="amount" value="<?=ev($doc,'total_amount')?>" required></div><div style="margin-top:14px"><label>ประเภทงบประมาณ</label><div class="checkbox-group"><?php foreach($types as $v=>$l):?><label><input type="checkbox" name="budget_types[]" value="<?=$v?>" <?=in_array($v,$selected,true)?'checked':''?>> <?=$l?></label><?php endforeach;?></div></div><div class="toolbar" style="margin-top:14px"><button class="btn btn-success">บันทึกการแก้ไข</button><a class="btn btn-muted" href="budget_detail.php?id=<?=$id?>">ยกเลิก</a></div></form></section></main></body></html>


